        /// <summary>
        /// Checks at start-up whether there are recent crash dumps and sets the BSOD badge.
        /// Runs once, in the background, without blocking the UI.
        /// </summary>
        private async Task CheckCrashBadgeOnStartupAsync()
        {
            try
            {
                // Short delay — lets the hardware init finish first
                await Task.Delay(3000);
                var crashes = await _crashService.GetCrashesAsync();
                int realCrashes = crashes.Count(c =>
                    !string.IsNullOrEmpty(c.StopCode) && c.StopCode != "—");
                if (realCrashes > 0)
                    UpdateSidebarBadge("Crash", realCrashes);
            }
            catch (Exception ex) { AppLogger.Warning(ex, "CheckCrashBadgeOnStartupAsync"); }
        }

        private async Task CheckEventsBadgeOnStartupAsync()
        {
            try
            {
                await Task.Delay(4000); // lets the rest of the initialization finish first
                DateTime sinceBoot;
                try { sinceBoot = DateTime.Now - SMDWin.Services.PowerOnClock.SinceOn; }   // since power-on: with Fast Startup Windows' uptime spans weeks
                catch { sinceBoot = DateTime.Today; } // a reasonable fallback, very unlikely to be needed
                var events = await _eventService.GetEventsAsync(sinceBoot, DateTime.Now.AddMinutes(1), "All");
                int realErrorCount = events.Count(ev => ev.Level == "Error" || ev.Level == "Critical");
                if (realErrorCount > 0)
                    UpdateSidebarBadge("Events", realErrorCount, $"{realErrorCount} error(s) since this PC started");
            }
            catch (Exception ex) { AppLogger.Warning(ex, "CheckEventsBadgeOnStartupAsync"); }
        }

        private bool _taskBadgeStressOn = false, _taskBadgeDiskOn = false, _taskBadgeBenchOn = false;
        private int _ramTaskActiveCount = 0;
        private void SetNavTaskBadge(string canvasName, bool busy)
        {
            try
            {
                switch (canvasName)
                {
                    case "TaskBadgeStress":
                        if (_taskBadgeStressOn == busy) return; // evitam invalidare layout redundanta
                        _taskBadgeStressOn = busy;
                        if (TaskBadgeStress != null)
                            TaskBadgeStress.Visibility = busy ? Visibility.Visible : Visibility.Collapsed;
                        break;
                    case "TaskBadgeDisk":
                        if (_taskBadgeDiskOn == busy) return;
                        _taskBadgeDiskOn = busy;
                        if (TaskBadgeDisk != null)
                            TaskBadgeDisk.Visibility = busy ? Visibility.Visible : Visibility.Collapsed;
                        break;
                    case "TaskBadgeBench":
                        if (_taskBadgeBenchOn == busy) return;
                        _taskBadgeBenchOn = busy;
                        if (FindName("TaskBadgeBench") is FrameworkElement tbb)
                            tbb.Visibility = busy ? Visibility.Visible : Visibility.Collapsed;
                        break;
                    case "TaskBadgeRam":
                        _ramTaskActiveCount = Math.Max(0, _ramTaskActiveCount + (busy ? 1 : -1));
                        if (TaskBadgeRam != null)
                            TaskBadgeRam.Visibility = _ramTaskActiveCount > 0 ? Visibility.Visible : Visibility.Collapsed;
                        break;
                }
                UpdateTaskBadgeSpinTimerState();
                UpdateLogoActivity();   // the sidebar logo and the taskbar button follow the running tests
            }
            catch (Exception ex) { AppLogger.Debug($"SetNavTaskBadge({canvasName}): {ex.Message}"); }
        }

        /// <summary>Chooses which glyph (dot/ring/hourglass/bolt/squares) is visible inside each TaskBadge, from
        /// SettingsService.Current.TaskBadgeStyle. Called once at start (after the settings load) and again every time the user
        /// changes the style in Design Lab — it has nothing to do with the Visibility of the badge itself (that stays
        /// exclusively with SetNavTaskBadge, i.e. "is a test running or not").</summary>
        public void ApplyTaskBadgeStyle()
        {
            try
            {
                string style = SettingsService.Current.TaskBadgeStyle;
                foreach (var prefix in new[] { "TaskBadgeStress", "TaskBadgeDisk", "TaskBadgeRam", "TaskBadgeBench" })
                {
                    var dot  = FindName(prefix + "Dot")       as FrameworkElement;
                    var ring = FindName(prefix + "Ring")      as FrameworkElement;
                    var hg   = FindName(prefix + "Hourglass") as FrameworkElement;
                    var bolt = FindName(prefix + "Bolt")      as FrameworkElement;
                    if (dot  != null) dot.Visibility  = (style == "Dot" || style == "Pulse") ? Visibility.Visible : Visibility.Collapsed;
                    if (ring != null) ring.Visibility = style == "SpinRing"  ? Visibility.Visible : Visibility.Collapsed;
                    if (hg   != null) hg.Visibility   = style == "Hourglass" ? Visibility.Visible : Visibility.Collapsed;
                    if (bolt != null) bolt.Visibility = style == "Bolt"      ? Visibility.Visible : Visibility.Collapsed;
                    if (FindName(prefix + "Squares") is TaskBadgeSquares sq)
                    {
                        bool squares = SquareBadgeAnim.IsSquareStyle(style);
                        sq.Visibility = squares ? Visibility.Visible : Visibility.Collapsed;
                        if (squares) sq.Variant = style;
                    }
                    // The dot always returns to normal opacity/scale when "Pulse" is not the current style — otherwise it could stay half
                    // transparent if the user changes the style in the middle of a pulse.
                    if (style != "Pulse" && dot != null) { dot.Opacity = 1.0; dot.RenderTransform = System.Windows.Media.Transform.Identity; }
                }
            }
            catch (Exception ex) { AppLogger.Debug($"ApplyTaskBadgeStyle: {ex.Message}"); }
        }

        private double _taskBadgeAnimAngle = 0; // degrees — for the SpinRing style
        private int    _taskBadgeAnimStep  = 0; // ticks — for Pulse/Hourglass/Bolt (they need no degrees)
        private DispatcherTimer? _taskBadgeSpinTimer;
        // the sensor tick (OnTempTick) runs every 1-4 s, too rarely for a rotation that looks smooth. The ring needs its own,
        // much faster rhythm, but WITHOUT a Storyboard (see the comment at SetNavTaskBadge). A plain DispatcherTimer that only
        // sets an angle on each tick — no animation state of its own that could go out of sync, just started/stopped as needed
        // (see UpdateTaskBadgeSpinTimerState, called from SetNavTaskBadge).

        /// <summary>Starts/stops the fast rotation timer depending on whether at least one badge is active NOW — the timer does
        /// not tick for nothing while no test runs. Called from SetNavTaskBadge every time a badge turns on/off.</summary>
        private void UpdateTaskBadgeSpinTimerState()
        {
            try
            {
                bool anyActive = _taskBadgeStressOn || _taskBadgeDiskOn || _taskBadgeBenchOn || _ramTaskActiveCount > 0;
                if (anyActive && _taskBadgeSpinTimer == null)
                {
                    _taskBadgeSpinTimer = new DispatcherTimer { Interval = TimeSpan.FromMilliseconds(70) };
                    _taskBadgeSpinTimer.Tick += (_, _) => { AdvanceSpinRingFast(); AdvanceSquareBadges(); };
                    _taskBadgeSpinTimer.Start();
                }
                else if (!anyActive && _taskBadgeSpinTimer != null)
                {
                    _taskBadgeSpinTimer.Stop();
                    _taskBadgeSpinTimer = null;
                }
            }
            catch (Exception ex) { AppLogger.Debug($"UpdateTaskBadgeSpinTimerState: {ex.Message}"); }
        }

        /// <summary>Advances ONLY the ring rotation (SpinRing style), at its own rhythm above — the other styles
        /// (Pulse/Hourglass/Bolt) stay on the normal sensor tick, in AdvanceTaskBadgeAnim, where the slower step suits them
        /// visually anyway (a gentle pulse, an hourglass that flips, no continuous motion).</summary>
        private void AdvanceSpinRingFast()
        {
            try
            {
                if (SettingsService.Current.TaskBadgeStyle != "SpinRing") return;
                _taskBadgeAnimAngle = (_taskBadgeAnimAngle + 20) % 360; // 18 steps/turn at 70ms ≈ 1.26s/turn
                if (FindName("TaskBadgeStressRingRotate") is System.Windows.Media.RotateTransform r1) r1.Angle = _taskBadgeAnimAngle;
                if (FindName("TaskBadgeDiskRingRotate")   is System.Windows.Media.RotateTransform r2) r2.Angle = _taskBadgeAnimAngle;
                if (FindName("TaskBadgeRamRingRotate")    is System.Windows.Media.RotateTransform r3) r3.Angle = _taskBadgeAnimAngle;
                if (FindName("TaskBadgeBenchRingRotate")  is System.Windows.Media.RotateTransform r4) r4.Angle = _taskBadgeAnimAngle;
            }
            catch (Exception ex) { AppLogger.Debug($"AdvanceSpinRingFast: {ex.Message}"); }
        }

        /// <summary>Advances the square indicators (Square* styles), on the same fast timer as the ring.
        /// The phase is taken from the clock, not accumulated step by step: a late tick neither slows down nor breaks the
        /// animation. Nothing is drawn while the window is hidden.</summary>
        private void AdvanceSquareBadges()
        {
            try
            {
                string style = SettingsService.Current.TaskBadgeStyle;
                if (!SquareBadgeAnim.IsSquareStyle(style) || !_uiVisibleCached) return;
                double phase = SquareBadgeAnim.PhaseAt(style, Environment.TickCount64);
                if (_taskBadgeStressOn && FindName("TaskBadgeStressSquares") is TaskBadgeSquares s1) s1.Phase = phase;
                if (_taskBadgeDiskOn && FindName("TaskBadgeDiskSquares") is TaskBadgeSquares s2) s2.Phase = phase;
                if (_ramTaskActiveCount > 0 && FindName("TaskBadgeRamSquares") is TaskBadgeSquares s3) s3.Phase = phase;
                if (_taskBadgeBenchOn && FindName("TaskBadgeBenchSquares") is TaskBadgeSquares s4) s4.Phase = phase;
            }
            catch (Exception ex) { AppLogger.Debug($"AdvanceSquareBadges: {ex.Message}"); }
        }

        /// <summary>Advances the sidebar badge animation by ONE step, based on the current tick — called from OnTempTick, NEVER
        /// from a separate timer/Storyboard (see the comment at SetNavTaskBadge for the exact reason). Each call recomputes the
        /// visual state from scratch (angle/phase), it does not continue an animation with its own state — if a tick is skipped
        /// (e.g. during an Event Viewer scan), the next tick corrects it automatically, it does not stay "frozen" halfway.
        /// It no longer touches SpinRing — see AdvanceSpinRingFast/_taskBadgeSpinTimer above for why.</summary>
        private void AdvanceTaskBadgeAnim()
        {
            try
            {
                string style = SettingsService.Current.TaskBadgeStyle;
                if (style != "Pulse" && style != "Hourglass" && style != "Bolt") return;

                _taskBadgeAnimStep = (_taskBadgeAnimStep + 1) % 3600; // does not matter — only avoids a long-term overflow

                if (style == "Pulse")
                {
                    // Simple opacity pulse in 4 steps (1.0 -> 0.35 -> 1.0) — enough to see the "breathing" at the normal tick interval
                    // (1-4 s), without a faster timer just for this dot.
                    double[] steps = { 1.0, 0.65, 0.35, 0.65 };
                    double op = steps[_taskBadgeAnimStep % steps.Length];
                    if (FindName("TaskBadgeStressDot") is System.Windows.Shapes.Ellipse e1) e1.Opacity = op;
                    if (FindName("TaskBadgeDiskDot")   is System.Windows.Shapes.Ellipse e2) e2.Opacity = op;
                    if (FindName("TaskBadgeRamDot")    is System.Windows.Shapes.Ellipse e3) e3.Opacity = op;
                    if (FindName("TaskBadgeBenchDot")  is System.Windows.Shapes.Ellipse e4) e4.Opacity = op;
                }
                else if (style == "Hourglass")
                {
                    // Hourglass "flip" — a vertical flip every 2 ticks, not a continuous rotation (an hourglass that flips abruptly reads
                    // better than one that rotates smoothly).
                    double scaleY = (_taskBadgeAnimStep / 2 % 2 == 0) ? 1.0 : -1.0;
                    ApplyFlipY("TaskBadgeStressHourglass", scaleY);
                    ApplyFlipY("TaskBadgeDiskHourglass",   scaleY);
                    ApplyFlipY("TaskBadgeRamHourglass",    scaleY);
                    ApplyFlipY("TaskBadgeBenchHourglass",  scaleY);
                }
                else if (style == "Bolt")
                {
                    double op = (_taskBadgeAnimStep % 2 == 0) ? 1.0 : 0.4; // blink simplu
                    if (FindName("TaskBadgeStressBolt") is FrameworkElement b1) b1.Opacity = op;
                    if (FindName("TaskBadgeDiskBolt")   is FrameworkElement b2) b2.Opacity = op;
                    if (FindName("TaskBadgeRamBolt")    is FrameworkElement b3) b3.Opacity = op;
                    if (FindName("TaskBadgeBenchBolt")  is FrameworkElement b4) b4.Opacity = op;
                }
            }
            catch (Exception ex) { AppLogger.Debug($"AdvanceTaskBadgeAnim: {ex.Message}"); }
        }

        private void ApplyFlipY(string name, double scaleY)
        {
            if (FindName(name) is FrameworkElement el)
            {
                el.RenderTransformOrigin = new System.Windows.Point(0.5, 0.5);
                el.RenderTransform = new System.Windows.Media.ScaleTransform(1.0, scaleY);
            }
        }

