        private void UpdateNotifBadge()
        {
            Dispatcher.InvokeAsync(() =>
            {
                if (IcoBellEmpty == null || IcoBellFull == null || BtnNotifications == null) return;
                var entries = SMDWin.Services.NotificationCenter.Entries;
                int n = entries.Count;
                IcoBellEmpty.Visibility = n > 0 ? Visibility.Collapsed : Visibility.Visible;
                IcoBellFull.Visibility  = n > 0 ? Visibility.Visible   : Visibility.Collapsed;
                BtnNotifications.ToolTip = SMDWin.Views.NotificationCenterWindow.BuildTooltipSummary();

                // The bell has the colour of the most serious notification left in the list (red = critical, orange = warning) and stays
                // that way until the notification is removed — opening the list does not "turn it off".
                if (FindName("PathBellFull") is System.Windows.Shapes.Path bell)
                    bell.SetResourceReference(System.Windows.Shapes.Shape.FillProperty,
                        SMDWin.Services.NotificationCenter.HighestSeverity() switch
                        {
                            SMDWin.Services.NotifSeverity.Critical => "StatusCritBrush",
                            SMDWin.Services.NotifSeverity.Warning  => "StatusWarnBrush",
                            _                                      => "TextPrimaryBrush",
                        });

                // New notification (not a removal and not the first display): the bell swings briefly
                var newest = n > 0 ? entries[0] : null;
                if (newest != null && newest.Id != _notifNewestSeen && (DateTime.UtcNow - newest.TimeUtc).TotalSeconds < 5)
                    WiggleNotifBell();
                _notifNewestSeen = newest?.Id ?? Guid.Empty;
            });
        }

        private Guid _notifNewestSeen = Guid.Empty;

        /// <summary>Bell swing on a new notification: a few fading oscillations, under one second.</summary>
        private void WiggleNotifBell()
        {
            try
            {
                if (!SMDWin.Services.SettingsService.Current.EnableAnimations) return;
                if (FindName("BellIconBox") is not FrameworkElement box) return;
                var rotate = new System.Windows.Media.RotateTransform(0);
                box.RenderTransformOrigin = new System.Windows.Point(0.5, 0.15);   // swings from its "hook"
                box.RenderTransform = rotate;
                var swing = new System.Windows.Media.Animation.DoubleAnimationUsingKeyFrames
                {
                    Duration = TimeSpan.FromMilliseconds(850),
                };
                foreach (var (at, angle) in new[] { (0.0, 0.0), (0.12, 16.0), (0.28, -13.0), (0.44, 9.0), (0.60, -6.0), (0.78, 3.0), (1.0, 0.0) })
                    swing.KeyFrames.Add(new System.Windows.Media.Animation.EasingDoubleKeyFrame(angle,
                        System.Windows.Media.Animation.KeyTime.FromPercent(at),
                        new System.Windows.Media.Animation.SineEase { EasingMode = System.Windows.Media.Animation.EasingMode.EaseInOut }));
                rotate.BeginAnimation(System.Windows.Media.RotateTransform.AngleProperty, swing);
            }
            catch (Exception ex) { AppLogger.Debug($"WiggleNotifBell: {ex.Message}"); }
        }

        private static readonly TimeSpan HealthCheckRecheckInterval = TimeSpan.FromHours(24);

        private async Task RunBackgroundHealthCheckAsync()
        {
            try
            {
                var s = SMDWin.Services.SettingsService.Current;
                bool dueForRecheck = s.HealthCheckLastRunUtc == null
                    || (DateTime.UtcNow - s.HealthCheckLastRunUtc.Value) >= HealthCheckRecheckInterval;
                if (!dueForRecheck) return;

                var orchestrator = new SMDWin.Services.DiagnosticOrchestrator();
                var results = await orchestrator.RunHealthCheckAsync("C:", CancellationToken.None,
                    getThrottleSnapshot: () => LastThrottleSnapshotPublic, includeWindowsUpdate: false);

                var counted = results.Where(r => !r.Skip).ToList();
                int critical = counted.Count(r => r.Severity == SMDWin.Services.DiagnosticSeverity.Critical);
                int warning  = counted.Count(r => r.Severity == SMDWin.Services.DiagnosticSeverity.Warning);
                s.HealthCheckLastSeverity = critical > 0 ? "Critical" : warning > 0 ? "Warning" : "Ok";
                s.HealthCheckLastCritical = critical;
                s.HealthCheckLastDanger = counted.Any(SMDWin.Services.DiagnosticOrchestrator.IsPhysicalDanger);
                s.HealthCheckLastWarning = warning;
                s.HealthCheckLastRunUtc = DateTime.UtcNow;
                SMDWin.Services.SettingsService.Save();
                UpdateHealthCheckBadge();
            }
            catch (Exception ex) { AppLogger.Debug($"RunBackgroundHealthCheckAsync: {ex.Message}"); }
        }

        public void UpdateHealthCheckBadge()
        {
            Dispatcher.InvokeAsync(() =>
            {
                var s = SMDWin.Services.SettingsService.Current;
                // The dot: grey = not checked yet, green = all OK, orange = things to check, red = problems.
                // Their number is only in the tooltip (known only after the check).
                string key = s.HealthCheckLastSeverity switch
                {
                    "Critical" => "StatusProblemBrush",
                    "Warning"  => "StatusCheckBrush",
                    "Ok"       => "StatusGoodBrush",
                    _          => "StatusNaBrush",
                };
                if (FindName("HealthDot") is System.Windows.Shapes.Ellipse dot)
                    dot.SetResourceReference(System.Windows.Shapes.Shape.FillProperty, key);
                UpdateAuroraAlert();   // the Dark background follows the same state as the dot

                if (FindName("BtnHealthCheck") is System.Windows.Controls.Border btn)
                {
                    string when = s.HealthCheckLastRunUtc?.ToLocalTime().ToString("dd MMM HH:mm") ?? "";
                    int crit = Math.Max(0, s.HealthCheckLastCritical), warn = Math.Max(0, s.HealthCheckLastWarning);
                    btn.ToolTip = s.HealthCheckLastSeverity switch
                    {
                        "None" or "" or null => LanguageService.S("Health", "TipNotRun", "Health check — not run yet"),
                        "Ok"   => string.Format(LanguageService.S("Health", "TipOk", "Health check — everything OK · {0}"), when),
                        _      => string.Format(LanguageService.S("Health", "TipIssues", "Health check — {0} problems, {1} to check · {2}"), crit, warn, when),
                    };
                }
            });
        }

