        public void UpdateSidebarBadge(string section, int count, string? reason = null, int severity = -1)
        {
            Dispatcher.InvokeAsync(() =>
            {
                switch (section)
                {
                    case "Events":
                        if (BadgeEvents != null && TxtBadgeEvents != null)
                        {
                            BadgeEvents.Visibility = count > 0 ? Visibility.Visible : Visibility.Collapsed;
                            TxtBadgeEvents.Text = "!";
                            BadgeEvents.ToolTip = string.IsNullOrEmpty(reason) ? null : reason;
                        }
                        break;
                    case "Crash":
                        if (BadgeCrash != null && TxtBadgeCrash != null)
                        {
                            BadgeCrash.Visibility = count > 0 ? Visibility.Visible : Visibility.Collapsed;
                            TxtBadgeCrash.Text = "!";
                        }
                        break;
                    case "Drivers":
                        if (BadgeDrivers != null && TxtBadgeDrivers != null)
                        {
                            BadgeDrivers.Visibility = count > 0 ? Visibility.Visible : Visibility.Collapsed;
                            TxtBadgeDrivers.Text = "!";
                        }
                        break;
                    case "Temp":
                        if (BadgeTemp != null && TxtBadgeTemp != null)
                        {
                            BadgeTemp.Visibility = count > 0 ? Visibility.Visible : Visibility.Collapsed;
                            TxtBadgeTemp.Text = "!";
                            int effectiveSeverity = severity >= 0 ? severity : (count >= 2 ? 2 : count);
                            // Red for critical (level 2), orange for warning (level 1)
                            BadgeTemp.Background = new SolidColorBrush(
                                effectiveSeverity >= 2 ? WpfColor.FromRgb(0xE8, 0x19, 0x2C)
                                                       : WpfColor.FromRgb(0xF5, 0x9E, 0x0B));
                            BadgeTemp.ToolTip = string.IsNullOrEmpty(reason) ? null : reason;
                        }
                        break;
                    case "Disk":
                        if (BadgeDisk != null && TxtBadgeDisk != null)
                        {
                            BadgeDisk.Visibility = count > 0 ? Visibility.Visible : Visibility.Collapsed;
                            TxtBadgeDisk.Text = "!";
                            BadgeDisk.ToolTip = string.IsNullOrEmpty(reason) ? null : reason;
                        }
                        break;
                    case "Battery":
                        if (BadgeBattery != null && TxtBadgeBattery != null)
                        {
                            BadgeBattery.Visibility = count > 0 ? Visibility.Visible : Visibility.Collapsed;
                            TxtBadgeBattery.Text = "!";
                        }
                        break;
                }
            });
        }
    }
